def evaluate(current_reputation, observation, my_history, round_num):
    # Use exponential smoothing to update reputation based on observed action.
    # Assume action 'B' is cooperative.
    alpha = 0.2
    if observation['action'] == 'B':
        rep_update = 1.0
    else:
        rep_update = -1.0
    new_rep = (1 - alpha) * current_reputation + alpha * rep_update
    return max(-1.0, min(1.0, new_rep))

def decide(recipient_reputation, round_num, my_history):
    # Count own cooperative actions (False corresponds to cooperative move).
    coop = sum(1 for h in my_history if h.get('action') == False)
    total = len(my_history)
    coop_rate = coop / total if total > 0 else 0.5

    # Dynamic threshold based on round and own cooperation rate.
    if round_num < 10:
        threshold = -0.3  # generous early
    elif coop_rate < 0.3 and total > 5:
        threshold = -0.2  # repair own reputation if defecting too much
    else:
        threshold = 0.1   # standard conditional cooperator

    # Cooperate (return False) only if recipient reputation is above threshold.
    return recipient_reputation <= threshold
